    for i in range(n):
        if occ[i] <= 0 or radii[i] <= 0:
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or group < 14 or group > 17 or en is None or en < 2.5:
            continue
        expected = 18.0 - group
        coordination = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or radii[j] <= 0:
                continue
            ratio = d / (radii[i] + radii[j])
            contact = min(1.0, max(0.0, 1.35 - ratio) ** 2 / 0.1225)
            coordination += occ[j] * contact
        total += occ[i] * max(0.0, expected - coordination) / expected
    return float(total / amount)
